document.addEventListener('DOMContentLoaded', function () {
    const menuToggle = document.getElementById('menu-toggle');
    const header = document.getElementById('header');

    if (menuToggle && header) {
      menuToggle.addEventListener('click', function (e) {
        e.preventDefault();
        header.classList.toggle('show-menu');
        const expanded = menuToggle.getAttribute('aria-expanded') === 'true' || false;
        menuToggle.setAttribute('aria-expanded', !expanded);
      });

      // Close menu when clicking on menu items (for mobile)
      document.querySelectorAll('.menu a').forEach(function (item) {
        item.addEventListener('click', function () {
          header.classList.remove('show-menu');
          menuToggle.setAttribute('aria-expanded', 'false');
        });
      });

      // Close menu when clicking outside
      document.addEventListener('click', function (e) {
        if (!header.contains(e.target) && header.classList.contains('show-menu')) {
          header.classList.remove('show-menu');
          menuToggle.setAttribute('aria-expanded', 'false');
        }
      });
    }

    // Back-to-top button scroll toggle
    var backToTop = document.querySelector('.back-to-top');
    if (backToTop) {
      window.addEventListener('scroll', function () {
        if (window.scrollY > 400) {
          backToTop.classList.add('show');
        } else {
          backToTop.classList.remove('show');
        }
      }, { passive: true });
    }

    // Header scroll effect
    if (header) {
      window.addEventListener('scroll', function () {
        if (window.scrollY > 50) {
          header.classList.add('scrolled');
        } else {
          header.classList.remove('scrolled');
        }
      }, { passive: true });
    }

    // ===== SCROLL-TRIGGERED REVEAL ANIMATIONS =====
    var prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

    if (!prefersReducedMotion) {
      // Reveal elements: .reveal, .reveal-left, .reveal-right
      var revealElements = document.querySelectorAll('.reveal, .reveal-left, .reveal-right');

      var revealObserver = new IntersectionObserver(function (entries) {
        entries.forEach(function (entry) {
          if (entry.isIntersecting) {
            entry.target.classList.add('revealed');
            revealObserver.unobserve(entry.target);
          }
        });
      }, {
        threshold: 0.12,
        rootMargin: '0px 0px -60px 0px'
      });

      revealElements.forEach(function (el) {
        revealObserver.observe(el);
      });

      // Instagram grid items — staggered reveal
      var instagramItems = document.querySelectorAll('.instagram-grid-item');
      var igObserver = new IntersectionObserver(function (entries) {
        entries.forEach(function (entry) {
          if (entry.isIntersecting) {
            // Stagger each item within the grid
            var items = entry.target.parentElement.querySelectorAll('.instagram-grid-item');
            items.forEach(function (item, i) {
              setTimeout(function () {
                item.classList.add('revealed');
              }, i * 60);
            });
            igObserver.unobserve(entry.target);
          }
        });
      }, {
        threshold: 0.1,
        rootMargin: '0px 0px -40px 0px'
      });

      if (instagramItems.length > 0) {
        igObserver.observe(instagramItems[0]);
      }

      // FAQ items — staggered reveal
      var faqItems = document.querySelectorAll('.faq-preview-item');
      var faqObserver = new IntersectionObserver(function (entries) {
        entries.forEach(function (entry) {
          if (entry.isIntersecting) {
            var siblings = entry.target.parentElement.querySelectorAll('.faq-preview-item');
            siblings.forEach(function (item, i) {
              setTimeout(function () {
                item.classList.add('revealed');
              }, i * 100);
            });
            faqObserver.unobserve(entry.target);
          }
        });
      }, {
        threshold: 0.1,
        rootMargin: '0px 0px -40px 0px'
      });

      if (faqItems.length > 0) {
        faqObserver.observe(faqItems[0]);
      }

      // Contact items — staggered reveal
      var contactItems = document.querySelectorAll('.contact-item');
      var contactObserver = new IntersectionObserver(function (entries) {
        entries.forEach(function (entry) {
          if (entry.isIntersecting) {
            var siblings = entry.target.parentElement.querySelectorAll('.contact-item');
            siblings.forEach(function (item, i) {
              setTimeout(function () {
                item.classList.add('revealed');
              }, i * 80);
            });
            contactObserver.unobserve(entry.target);
          }
        });
      }, {
        threshold: 0.1,
        rootMargin: '0px 0px -40px 0px'
      });

      if (contactItems.length > 0) {
        contactObserver.observe(contactItems[0]);
      }

      // Active nav highlight on scroll
      var sections = document.querySelectorAll('section[id]');
      var navLinks = document.querySelectorAll('.main-nav .menu li a[href^="#"]');

      var navObserver = new IntersectionObserver(function (entries) {
        entries.forEach(function (entry) {
          if (entry.isIntersecting) {
            var id = entry.target.getAttribute('id');
            navLinks.forEach(function (link) {
              link.classList.remove('active');
              if (link.getAttribute('href') === '#' + id) {
                link.classList.add('active');
              }
            });
          }
        });
      }, {
        threshold: 0.3,
        rootMargin: '-80px 0px -50% 0px'
      });

      sections.forEach(function (section) {
        navObserver.observe(section);
      });
    } else {
      // Reduced motion: show everything immediately
      document.querySelectorAll('.reveal, .reveal-left, .reveal-right, .instagram-grid-item, .faq-preview-item, .contact-item').forEach(function (el) {
        el.classList.add('revealed');
      });
    }
  });